import csv,collections
X='scratchpad/session_2026-11-22-icf-umbrella-glossary/who/SimpleTabulation-ICF-en.txt'
rows=list(csv.reader(open(X,encoding='utf-8-sig'),delimiter='\t'))
h=rows[0]; print(h)
R=[dict(zip(h,r)) for r in rows[1:]]
print(len(R), collections.Counter(r['ClassKind'] for r in R))
by={r['Foundation URI']:r for r in R}
kids=collections.defaultdict(list)
for r in R: kids[r['Parent']].append(r)
def show(uri,d=0,maxd=9):
    r=by[uri]; print('  '*d+(r['Code'] or r['BlockId'])+' '+r['Title'].strip('"').lstrip('- ').strip()+' ['+r['ClassKind']+']')
    if d<maxd:
        for k in kids[uri]: show(k['Foundation URI'],d+1,maxd)
# find b7 chapter-ish
for r in R:
    if r['Title'].strip('"').lstrip('- ').strip() in ('Movement functions','Neuromusculoskeletal and movement-related functions','Sensory functions of pain','Hearing and vestibular functions','Seeing and related functions','Pain'):
        print('FOUND',r['Code'] or r['BlockId'],r['Title'],r['ClassKind'])
